WITH with_gaps AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) > INTERVAL 60 DAYS THEN 1 ELSE 0 END AS is_new_session FROM transactions), sessions_transactions AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT txn_type, DATE_TRUNC('YEAR', txn_time) AS year_start, PERCENTILE_APPROX(amount, 0.9) AS amount_p90, COUNT(DISTINCT merchant) AS distinct_merchants, SUM(amount) FILTER (WHERE merchant = 'Starbucks') AS starbucks_total_amount FROM sessions_transactions GROUP BY 1, 2 HAVING SUM(amount) FILTER (WHERE merchant = 'Starbucks') > 0
